package org.eclipse.tycho.pomless;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.lang.reflect.Field;

import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Regression test for the IS_FIRST ThreadLocal bug in TychoAggregatorMapping.
 *
 * The bug: after scanning the first aggregator directory, IS_FIRST.remove() is called,
 * which causes ThreadLocal.withInitial(() -> true) to fire again on the next get().
 * This resets the value to true, causing unwanted scanning for subsequent aggregator
 * directories.
 *
 * Correct behavior: after the first scan, IS_FIRST.get() should return false for all
 * subsequent calls in the same thread, so only the FIRST aggregator directory is scanned.
 */
public class TychoAggregatorMappingIsFirstTest {

    private ThreadLocal<Boolean> isFirst;

    @Before
    public void setup() throws Exception {
        // Access the IS_FIRST ThreadLocal via reflection
        try {
            Field isField = TychoAggregatorMapping.class.getDeclaredField("IS_FIRST");
            isField.setAccessible(true);
            isFirst = (ThreadLocal<Boolean>) isField.get(null);
        } catch (NoSuchFieldException e) {
            // IS_FIRST field does not exist (e.g., old code using COMMON_NAMES approach)
            // In that case, there's no ThreadLocal bug to test - just skip
            isFirst = null;
        }
    }

    @After
    public void cleanup() {
        // Reset the ThreadLocal so other tests are not affected
        if (isFirst != null) {
            isFirst.remove();
        }
    }

    @Test
    public void testWithInitialReturnsTrueOnFirstGet() {
        if (isFirst == null) {
            // Old code without IS_FIRST field - no bug to test
            return;
        }
        // Clean state: remove any prior value
        isFirst.remove();
        // First get() should call withInitial and return true
        Boolean value = isFirst.get();
        assertNotNull("IS_FIRST.get() should return a non-null Boolean", value);
        assertTrue("IS_FIRST.get() should return true on first access (withInitial)", value.booleanValue());
    }

    @Test
    public void testThreadLocalSetFalseThenGetShouldReturnFalse() {
        if (isFirst == null) {
            // Old code without IS_FIRST field - no bug to test
            return;
        }
        // After setting false, subsequent get() should return false
        isFirst.remove();
        isFirst.get(); // trigger withInitial -> true
        isFirst.set(false);

        assertFalse("IS_FIRST.get() should return false after set(false)", isFirst.get().booleanValue());
    }

    @Test
    public void testThreadLocalSetFalseThenRemoveThenGetShouldReturnFalse() {
        if (isFirst == null) {
            // Old code without IS_FIRST field - no bug to test
            return;
        }
        // This test verifies the CORE BUG:
        //
        // In getPrimaryArtifact, the sequence is:
        //   1. isFirst.get() -> true (withInitial fires)
        //   2. isFirst.set(false)
        //   3. ... scanning happens ...
        //   4. isFirst.remove()  <-- BUG: this clears the ThreadLocal
        //
        // The correct fix would be to NOT call remove(), leaving the false value in place.
        // After remove(), the next get() fires withInitial again, returning true.
        //
        // This test asserts the CORRECT behavior: after set(false) + remove(),
        // subsequent get() should still return false (not true).
        // The current buggy code makes this assertion FAIL.

        isFirst.remove();          // clean state
        isFirst.get();             // step 1: withInitial -> true
        isFirst.set(false);        // step 2: set to false
        // ... scanning happens ...
        isFirst.remove();          // step 3: remove (THE BUG - causes withInitial to re-fire)

        // After remove(), IS_FIRST.get() should return false (correct behavior)
        // but with the BUG, it returns true (withInitial fires again)
        Boolean valueAfter = isFirst.get();
        assertNotNull("IS_FIRST.get() should return non-null after remove", valueAfter);

        assertFalse(
            "BUG: IS_FIRST.remove() causes withInitial(() -> true) to fire again on next get(). " +
            "After first aggregator scan, subsequent aggregator directories should NOT be scanned. " +
            "IS_FIRST.get() returned true after remove(), but should remain false. " +
            "Fix: remove the IS_FIRST.remove() call so the false value persists.",
            valueAfter.booleanValue()
        );
    }
}

